// server_Game/AstarPath.cpp — ExploreMap()
bool Astar::ExploreMap(int x, int y)
{
    // 속도 위해 AstarPathMaxSizeHalf(15) 안에서만 길찾기
    if (x < corCenter.x - AstarPathMaxSizeHalf || x > corCenter.x + AstarPathMaxSizeHalf ||
        y < corCenter.y - AstarPathMaxSizeHalf || y > corCenter.y + AstarPathMaxSizeHalf)
        return false;   // 윈도우 밖 = 못 감 → 탐색 폭발 차단

    return m_pGameMap->CheckEnterPos(corCenter.x, corCenter.y, x, y,
                                     m_idistance, USER_TYPE::USER_TYPE_NPC, 0, NULL);
}

